using System.Security.Claims;
using System.Text.RegularExpressions;
using BrewNest.Contracts.Sales;
using BrewNest.Modules.Sales.Domain.Entities;
using BrewNest.Modules.Sales.Infrastructure.Persistence;
using Microsoft.AspNetCore.Http;
using Microsoft.EntityFrameworkCore;

namespace BrewNest.Modules.Sales.Application.Services;

internal enum SalesResultStatus { Success,Validation,NotFound,Conflict }
internal sealed record SalesResult<T>(SalesResultStatus Status,T? Value,string[] Errors)
{
    public bool Succeeded=>Status==SalesResultStatus.Success;
    public static SalesResult<T> Success(T value)=>new(SalesResultStatus.Success,value,[]);
    public static SalesResult<T> Failure(SalesResultStatus status,params string[] errors)=>new(status,default,errors);
}
internal sealed record SalesRequestContext(string Actor)
{
    public static SalesRequestContext FromHttpContext(HttpContext context)=>new(context.User.FindFirstValue(ClaimTypes.NameIdentifier)??context.User.Identity?.Name??"anonymous");
}

internal sealed class SalesService(SalesDbContext database,ISalesCatalogPort catalog,ISalesDocumentNumberPort numbers,TimeProvider timeProvider)
{
    private DateTimeOffset Now=>timeProvider.GetUtcNow();

    public async Task<SalesResult<SalesOrderResponse[]>> GetOrdersAsync(string? status,CancellationToken token)
    {
        var query=FullQuery().AsNoTracking();if(!string.IsNullOrWhiteSpace(status)){if(!Enum.TryParse<OrderStatus>(status,true,out var parsed))return Validation<SalesOrderResponse[]>("Sales order status is invalid.");query=query.Where(x=>x.Status==parsed);}var values=await query.OrderByDescending(x=>x.CreatedAt).Take(500).ToArrayAsync(token);return SalesResult<SalesOrderResponse[]>.Success(values.Select(Map).ToArray());
    }
    public async Task<SalesResult<SalesOrderResponse>> GetOrderAsync(Guid id,CancellationToken token){var value=await FullQuery().AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,token);return value is null?NotFound<SalesOrderResponse>():SalesResult<SalesOrderResponse>.Success(Map(value));}
    public async Task<SalesResult<SalesReferenceDataResponse>> GetReferencesAsync(CancellationToken token)=>SalesResult<SalesReferenceDataResponse>.Success(await catalog.GetReferencesAsync(token));

    public async Task<SalesResult<SalesOrderResponse>> CreateAsync(CreateSalesOrderRequest request,SalesRequestContext context,CancellationToken token)
    {
        if(!Enum.TryParse<OrderType>(request.OrderType.ToString(),out var type))return Validation<SalesOrderResponse>("Order type is invalid.");var errors=await ValidateHeaderAsync(type,request.CustomerId,request.DiningTableId,request.CustomerName,request.CustomerPhone,request.DeliveryAddress,request.Notes,null,token);if(errors.Length>0)return Validation<SalesOrderResponse>(errors);
        var order=new SalesOrder{Id=Guid.NewGuid(),OrderNumber=numbers.NextOrderNumber(),OrderType=type,Status=OrderStatus.Draft,CustomerId=request.CustomerId,DiningTableId=request.DiningTableId,CustomerName=request.CustomerName.Trim(),CustomerPhone=request.CustomerPhone.Trim(),DeliveryAddress=request.DeliveryAddress.Trim(),Notes=request.Notes.Trim(),CreatedAt=Now,CreatedBy=context.Actor};database.Orders.Add(order);AddHistory(order,"None",OrderStatus.Draft.ToString(),"Order created.",context);return await SaveAsync(()=>Map(order),token);
    }
    public async Task<SalesResult<SalesOrderResponse>> UpdateAsync(Guid id,UpdateSalesOrderRequest request,SalesRequestContext context,CancellationToken token)
    {
        var order=await FullQuery().SingleOrDefaultAsync(x=>x.Id==id,token);if(order is null)return NotFound<SalesOrderResponse>();if(!CanAmend(order))return Conflict<SalesOrderResponse>("Only draft or confirmed orders may be amended.");if(!ApplyVersion(order,request.Version))return VersionFailure<SalesOrderResponse>();var errors=await ValidateHeaderAsync(order.OrderType,request.CustomerId,request.DiningTableId,request.CustomerName,request.CustomerPhone,request.DeliveryAddress,request.Notes,id,token);if(errors.Length>0)return Validation<SalesOrderResponse>(errors);order.CustomerId=request.CustomerId;order.DiningTableId=request.DiningTableId;order.CustomerName=request.CustomerName.Trim();order.CustomerPhone=request.CustomerPhone.Trim();order.DeliveryAddress=request.DeliveryAddress.Trim();order.Notes=request.Notes.Trim();Touch(order,context);return await SaveAsync(()=>Map(order),token);
    }
    public async Task<SalesResult<SalesOrderResponse>> AddLineAsync(Guid id,AddSalesOrderLineRequest request,SalesRequestContext context,CancellationToken token)
    {
        var order=await FullQuery().SingleOrDefaultAsync(x=>x.Id==id,token);if(order is null)return NotFound<SalesOrderResponse>();if(!CanAmend(order))return Conflict<SalesOrderResponse>("Items cannot be added after billing, closure, or cancellation.");if(!ApplyVersion(order,request.Version))return VersionFailure<SalesOrderResponse>();if(request.Quantity<=0)return Validation<SalesOrderResponse>("Quantity must be positive.");if(request.SpecialInstructions is null||request.SpecialInstructions.Length>500)return Validation<SalesOrderResponse>("Special instructions cannot exceed 500 characters.");var item=await catalog.GetMenuItemAsync(request.MenuItemId,token);if(item is null)return Validation<SalesOrderResponse>("The selected menu item is invalid or inactive.");CancelActiveDiscounts(order,"Order items changed after discount request.",context);var line=new SalesOrderLine{Id=Guid.NewGuid(),OrderId=order.Id,MenuItemId=item.Id,ItemCode=item.Code,ItemName=item.Name,Quantity=request.Quantity,UnitPrice=item.SalesPrice,SpecialInstructions=request.SpecialInstructions.Trim(),AddedAt=Now,AddedBy=context.Actor};order.Lines.Add(line);database.OrderLines.Add(line);Touch(order,context);return await SaveAsync(()=>Map(order),token);
    }
    public async Task<SalesResult<SalesOrderResponse>> UpdateLineAsync(Guid id,Guid lineId,UpdateSalesOrderLineRequest request,SalesRequestContext context,CancellationToken token)
    {
        var order=await FullQuery().SingleOrDefaultAsync(x=>x.Id==id,token);if(order is null)return NotFound<SalesOrderResponse>();if(!CanAmend(order))return Conflict<SalesOrderResponse>("Items cannot be changed after billing, closure, or cancellation.");var line=order.Lines.SingleOrDefault(x=>x.Id==lineId);if(line is null)return NotFound<SalesOrderResponse>();if(!ApplyVersion(order,request.OrderVersion)||!ApplyVersion(line,request.LineVersion))return VersionFailure<SalesOrderResponse>();if(line.IsCancelled)return Conflict<SalesOrderResponse>("Cancelled order lines cannot be reactivated or changed.");if(request.Quantity<=0)return Validation<SalesOrderResponse>("Quantity must be positive.");if(request.IsCancelled&&!ValidText(request.Reason,500))return Validation<SalesOrderResponse>("A cancellation reason up to 500 characters is required.");CancelActiveDiscounts(order,"Order items changed after discount request.",context);line.Quantity=request.Quantity;if(request.IsCancelled){line.IsCancelled=true;line.CancellationReason=request.Reason.Trim();}line.ModifiedAt=Now;line.ModifiedBy=context.Actor;Touch(order,context);return await SaveAsync(()=>Map(order),token);
    }
    public async Task<SalesResult<SalesOrderResponse>> RequestDiscountAsync(Guid id,RequestSalesDiscountRequest request,SalesRequestContext context,CancellationToken token)
    {
        var order=await FullQuery().SingleOrDefaultAsync(x=>x.Id==id,token);if(order is null)return NotFound<SalesOrderResponse>();if(!CanAmend(order))return Conflict<SalesOrderResponse>("Discounts cannot be requested after billing, closure, or cancellation.");if(!ApplyVersion(order,request.Version))return VersionFailure<SalesOrderResponse>();if(request.Percentage is <=0 or >100)return Validation<SalesOrderResponse>("Discount percentage must be greater than zero and no more than 100.");if(!ValidText(request.Reason,500))return Validation<SalesOrderResponse>("A discount reason up to 500 characters is required.");if(!order.Lines.Any(x=>!x.IsCancelled))return Conflict<SalesOrderResponse>("Add at least one active item before requesting a discount.");if(order.Discounts.Any(x=>x.Status==DiscountStatus.Pending))return Conflict<SalesOrderResponse>("This order already has a pending discount request.");CancelActiveDiscounts(order,"Replaced by a new discount request.",context);var gross=Gross(order);var discount=new SalesDiscount{Id=Guid.NewGuid(),OrderId=order.Id,Percentage=request.Percentage,Amount=Money(gross*request.Percentage/100m),Reason=request.Reason.Trim(),Status=DiscountStatus.Pending,RequestedBy=context.Actor,RequestedAt=Now};order.Discounts.Add(discount);database.Discounts.Add(discount);Touch(order,context);return await SaveAsync(()=>Map(order),token);
    }
    public async Task<SalesResult<SalesOrderResponse>> DecideDiscountAsync(Guid id,Guid discountId,DecideSalesDiscountRequest request,SalesRequestContext context,CancellationToken token)
    {
        var order=await FullQuery().SingleOrDefaultAsync(x=>x.Id==id,token);if(order is null)return NotFound<SalesOrderResponse>();if(!CanAmend(order))return Conflict<SalesOrderResponse>("Discount decisions are not allowed after billing, closure, or cancellation.");var discount=order.Discounts.SingleOrDefault(x=>x.Id==discountId);if(discount is null)return NotFound<SalesOrderResponse>();if(discount.Status!=DiscountStatus.Pending)return Conflict<SalesOrderResponse>("Only pending discounts may be decided.");if(!ApplyVersion(order,request.OrderVersion)||!ApplyVersion(discount,request.DiscountVersion))return VersionFailure<SalesOrderResponse>();if(request.Remarks is null||request.Remarks.Length>500)return Validation<SalesOrderResponse>("Decision remarks cannot exceed 500 characters.");discount.Status=request.Approve?DiscountStatus.Approved:DiscountStatus.Rejected;discount.Amount=Money(Gross(order)*discount.Percentage/100m);discount.ApprovedBy=context.Actor;discount.ApprovedAt=Now;discount.DecisionRemarks=request.Remarks.Trim();Touch(order,context);return await SaveAsync(()=>Map(order),token);
    }
    public Task<SalesResult<SalesOrderResponse>> ConfirmAsync(Guid id,ChangeSalesOrderStatusRequest request,SalesRequestContext context,CancellationToken token)=>ChangeStatusAsync(id,request,OrderStatus.Draft,OrderStatus.Confirmed,context,token,order=>order.Lines.Any(x=>!x.IsCancelled)?null:"An order requires at least one active item before confirmation.");
    public async Task<SalesResult<SalesOrderResponse>> BillAsync(Guid id,ChangeSalesOrderStatusRequest request,SalesRequestContext context,CancellationToken token)
    {
        var order=await FullQuery().SingleOrDefaultAsync(x=>x.Id==id,token);if(order is null)return NotFound<SalesOrderResponse>();if(order.Status!=OrderStatus.Confirmed)return Conflict<SalesOrderResponse>("Only confirmed orders may be billed.");if(!ApplyVersion(order,request.Version))return VersionFailure<SalesOrderResponse>();if(order.Discounts.Any(x=>x.Status==DiscountStatus.Pending))return Conflict<SalesOrderResponse>("An order cannot be finalized while a discount is awaiting approval.");if(!order.Lines.Any(x=>!x.IsCancelled))return Conflict<SalesOrderResponse>("An order requires at least one active item before billing.");var gross=Gross(order);var discount=order.Discounts.Where(x=>x.Status==DiscountStatus.Approved).OrderByDescending(x=>x.ApprovedAt).FirstOrDefault();var discountAmount=discount?.Amount??0m;var bill=new SalesBill{Id=Guid.NewGuid(),OrderId=order.Id,BillNumber=numbers.NextBillNumber(),GrossAmount=gross,DiscountAmount=discountAmount,NetAmount=gross-discountAmount,IssuedAt=Now,IssuedBy=context.Actor};order.Bill=bill;database.Bills.Add(bill);Transition(order,OrderStatus.Billed,string.IsNullOrWhiteSpace(request.Reason)?"Final bill issued.":request.Reason,context);return await SaveAsync(()=>Map(order),token);
    }
    public Task<SalesResult<SalesOrderResponse>> CloseAsync(Guid id,ChangeSalesOrderStatusRequest request,SalesRequestContext context,CancellationToken token)=>ChangeStatusAsync(id,request,OrderStatus.Billed,OrderStatus.Closed,context,token);
    public async Task<SalesResult<SalesOrderResponse>> CancelAsync(Guid id,ChangeSalesOrderStatusRequest request,SalesRequestContext context,CancellationToken token)
    {
        var order=await FullQuery().SingleOrDefaultAsync(x=>x.Id==id,token);if(order is null)return NotFound<SalesOrderResponse>();if(order.Status is not (OrderStatus.Draft or OrderStatus.Confirmed))return Conflict<SalesOrderResponse>("Only unbilled orders may be cancelled here. Billed voids belong to the Returns workflow.");if(!ApplyVersion(order,request.Version))return VersionFailure<SalesOrderResponse>();if(!ValidText(request.Reason,500))return Validation<SalesOrderResponse>("A cancellation reason up to 500 characters is required.");CancelActiveDiscounts(order,"Order cancelled.",context);Transition(order,OrderStatus.Cancelled,request.Reason,context);return await SaveAsync(()=>Map(order),token);
    }
    public async Task<SalesResult<SalesStatusHistoryResponse[]>> GetHistoryAsync(Guid? orderId,CancellationToken token){var query=database.StatusHistory.AsNoTracking();if(orderId is not null)query=query.Where(x=>x.OrderId==orderId);var values=await query.OrderByDescending(x=>x.ChangedAt).Take(500).ToArrayAsync(token);return SalesResult<SalesStatusHistoryResponse[]>.Success(values.Select(x=>new SalesStatusHistoryResponse(x.Id,x.OrderId,x.PreviousStatus,x.NewStatus,x.Reason,x.ChangedBy,x.ChangedAt)).ToArray());}

    private async Task<SalesResult<SalesOrderResponse>> ChangeStatusAsync(Guid id,ChangeSalesOrderStatusRequest request,OrderStatus expected,OrderStatus next,SalesRequestContext context,CancellationToken token,Func<SalesOrder,string?>? rule=null){var order=await FullQuery().SingleOrDefaultAsync(x=>x.Id==id,token);if(order is null)return NotFound<SalesOrderResponse>();if(order.Status!=expected)return Conflict<SalesOrderResponse>($"Only {expected} orders may move to {next}.");if(!ApplyVersion(order,request.Version))return VersionFailure<SalesOrderResponse>();var error=rule?.Invoke(order);if(error is not null)return Conflict<SalesOrderResponse>(error);Transition(order,next,string.IsNullOrWhiteSpace(request.Reason)?$"Order moved to {next}.":request.Reason,context);return await SaveAsync(()=>Map(order),token);}
    private IQueryable<SalesOrder> FullQuery()=>database.Orders.AsSplitQuery().Include(x=>x.Lines).Include(x=>x.Discounts).Include(x=>x.Bill);
    private async Task<string[]> ValidateHeaderAsync(OrderType type,Guid? customerId,Guid? tableId,string customerName,string phone,string address,string notes,Guid? currentId,CancellationToken token){var errors=new List<string>();if(customerName is null||customerName.Length>200)errors.Add("Customer name cannot exceed 200 characters.");if(phone is null||phone.Length>16)errors.Add("Customer phone cannot exceed 16 characters.");else if(!string.IsNullOrWhiteSpace(phone)&&!Regex.IsMatch(phone.Trim(),@"^\+[1-9][0-9]{7,14}$",RegexOptions.CultureInvariant))errors.Add("Customer phone must include a country code and 8 to 15 digits, for example +923001234567.");if(address is null||address.Length>500)errors.Add("Delivery address cannot exceed 500 characters.");if(notes is null||notes.Length>1000)errors.Add("Notes cannot exceed 1,000 characters.");if(customerId is not null&&!await catalog.IsCustomerActiveAsync(customerId.Value,token))errors.Add("The selected customer is invalid or inactive.");if(type==OrderType.DineIn){if(tableId is null)errors.Add("Dine-in orders require a dining table.");else if(!await catalog.IsDiningTableActiveAsync(tableId.Value,token))errors.Add("The selected dining table is invalid or inactive.");else if(await database.Orders.AnyAsync(x=>x.Id!=currentId&&x.DiningTableId==tableId&&x.Status!=OrderStatus.Closed&&x.Status!=OrderStatus.Cancelled,token))errors.Add("The selected dining table already has an active order.");}else if(tableId is not null)errors.Add("Only dine-in orders may have a dining table.");if(type==OrderType.Delivery&&(!ValidText(customerName,200)||!ValidText(phone,16)||!ValidText(address,500)))errors.Add("Delivery orders require customer name, phone, and delivery address.");return errors.ToArray();}
    private void CancelActiveDiscounts(SalesOrder order,string reason,SalesRequestContext context){foreach(var discount in order.Discounts.Where(x=>x.Status is DiscountStatus.Pending or DiscountStatus.Approved)){discount.Status=DiscountStatus.Cancelled;discount.ApprovedBy=context.Actor;discount.ApprovedAt=Now;discount.DecisionRemarks=reason;}}
    private void Transition(SalesOrder order,OrderStatus next,string reason,SalesRequestContext context){var previous=order.Status.ToString();order.Status=next;Touch(order,context);AddHistory(order,previous,next.ToString(),reason.Trim(),context);}
    private void AddHistory(SalesOrder order,string previous,string next,string reason,SalesRequestContext context)=>database.StatusHistory.Add(new(){Id=Guid.NewGuid(),OrderId=order.Id,PreviousStatus=previous,NewStatus=next,Reason=reason,ChangedBy=context.Actor,ChangedAt=Now});
    private void Touch(SalesOrder order,SalesRequestContext context){order.ModifiedAt=Now;order.ModifiedBy=context.Actor;}
    private bool ApplyVersion(SalesOrder value,string version)=>!database.Database.IsRelational()?IsValidVersion(version):ApplyVersionCore(database.Entry(value).Property(x=>x.RowVersion),version);private bool ApplyVersion(SalesOrderLine value,string version)=>!database.Database.IsRelational()?IsValidVersion(version):ApplyVersionCore(database.Entry(value).Property(x=>x.RowVersion),version);private bool ApplyVersion(SalesDiscount value,string version)=>!database.Database.IsRelational()?IsValidVersion(version):ApplyVersionCore(database.Entry(value).Property(x=>x.RowVersion),version);
    private static bool ApplyVersionCore<TEntity>(Microsoft.EntityFrameworkCore.ChangeTracking.PropertyEntry<TEntity,byte[]> property,string version) where TEntity:class{try{var bytes=Convert.FromBase64String(version);if(bytes.Length==0&&property.CurrentValue.Length==0)return true;property.OriginalValue=bytes;return bytes.Length>0;}catch(FormatException){return false;}}
    private static bool IsValidVersion(string version){try{Convert.FromBase64String(version);return true;}catch(FormatException){return false;}}
    private async Task<SalesResult<T>> SaveAsync<T>(Func<T> factory,CancellationToken token){try{await database.SaveChangesAsync(token);return SalesResult<T>.Success(factory());}catch(DbUpdateConcurrencyException exception) when(!database.Database.IsRelational()){foreach(var entry in exception.Entries){var current=await entry.GetDatabaseValuesAsync(token);if(current is null)return VersionFailure<T>();entry.OriginalValues.SetValues(current);}await database.SaveChangesAsync(token);return SalesResult<T>.Success(factory());}catch(DbUpdateConcurrencyException){return VersionFailure<T>();}catch(DbUpdateException){return Conflict<T>("The Sales change conflicts with current data.");}}
    private static bool CanAmend(SalesOrder order)=>order.Status is OrderStatus.Draft or OrderStatus.Confirmed;private static bool ValidText(string? value,int maximum)=>!string.IsNullOrWhiteSpace(value)&&value.Trim().Length<=maximum;private static decimal Money(decimal value)=>decimal.Round(value,2,MidpointRounding.AwayFromZero);private static decimal Gross(SalesOrder order)=>Money(order.Lines.Where(x=>!x.IsCancelled).Sum(x=>x.Quantity*x.UnitPrice));private static decimal Discount(SalesOrder order)=>order.Discounts.Where(x=>x.Status==DiscountStatus.Approved).OrderByDescending(x=>x.ApprovedAt).Select(x=>x.Amount).FirstOrDefault();
    private static SalesOrderResponse Map(SalesOrder x){var gross=Gross(x);var discount=x.Bill?.DiscountAmount??Discount(x);return new(x.Id,x.OrderNumber,Enum.Parse<SalesOrderType>(x.OrderType.ToString()),Enum.Parse<SalesOrderStatus>(x.Status.ToString()),x.CustomerId,x.DiningTableId,x.CustomerName,x.CustomerPhone,x.DeliveryAddress,x.Notes,gross,discount,gross-discount,x.Lines.OrderBy(y=>y.AddedAt).Select(Map).ToArray(),x.Discounts.OrderByDescending(y=>y.RequestedAt).Select(Map).ToArray(),x.Bill is null?null:new(x.Bill.Id,x.Bill.BillNumber,x.Bill.GrossAmount,x.Bill.DiscountAmount,x.Bill.NetAmount,x.Bill.IssuedAt,x.Bill.IssuedBy),x.CreatedAt,x.CreatedBy,Version(x.RowVersion));}
    private static SalesOrderLineResponse Map(SalesOrderLine x)=>new(x.Id,x.MenuItemId,x.ItemCode,x.ItemName,x.Quantity,x.UnitPrice,Money(x.Quantity*x.UnitPrice),x.SpecialInstructions,x.IsCancelled,x.CancellationReason,Version(x.RowVersion));
    private static SalesDiscountResponse Map(SalesDiscount x)=>new(x.Id,x.Percentage,x.Amount,x.Reason,Enum.Parse<SalesDiscountStatus>(x.Status.ToString()),x.RequestedBy,x.RequestedAt,x.ApprovedBy,x.ApprovedAt,x.DecisionRemarks,Version(x.RowVersion));
    private static string Version(byte[] value)=>Convert.ToBase64String(value);private static SalesResult<T> Validation<T>(params string[] errors)=>SalesResult<T>.Failure(SalesResultStatus.Validation,errors);private static SalesResult<T> Conflict<T>(string error)=>SalesResult<T>.Failure(SalesResultStatus.Conflict,error);private static SalesResult<T> NotFound<T>()=>SalesResult<T>.Failure(SalesResultStatus.NotFound,"The Sales order was not found.");private static SalesResult<T> VersionFailure<T>()=>Conflict<T>("The Sales record changed. Reload it and try again.");
}
